PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE games (
  slug        TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  tagline     TEXT NOT NULL,
  emoji       TEXT NOT NULL,
  kind        TEXT NOT NULL,                    
  href        TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'draft',    
  sort_order  INTEGER NOT NULL DEFAULT 0
, color TEXT NOT NULL DEFAULT '#7c3aed', card_colors TEXT NOT NULL DEFAULT '["#f59e0b","#2563eb"]');
CREATE TABLE dilemmas (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  category    TEXT NOT NULL,
  option_a    TEXT NOT NULL,
  option_b    TEXT NOT NULL,
  votes_a     INTEGER NOT NULL DEFAULT 0,
  votes_b     INTEGER NOT NULL DEFAULT 0,
  status      TEXT NOT NULL DEFAULT 'draft',
  source      TEXT NOT NULL DEFAULT 'seed',     
  created_at  INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE ranking_lists (
  slug        TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  question    TEXT NOT NULL,                    
  emoji       TEXT NOT NULL DEFAULT '🏆',
  status      TEXT NOT NULL DEFAULT 'draft',
  sort_order  INTEGER NOT NULL DEFAULT 0
, color TEXT NOT NULL DEFAULT '#7c3aed', card_colors TEXT NOT NULL DEFAULT '["#f59e0b","#2563eb"]');
CREATE TABLE ranking_entries (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  list_slug   TEXT NOT NULL REFERENCES ranking_lists (slug) ON DELETE CASCADE,
  label       TEXT NOT NULL,
  rating      REAL NOT NULL DEFAULT 1500,
  matches     INTEGER NOT NULL DEFAULT 0,
  wins        INTEGER NOT NULL DEFAULT 0,
  status      TEXT NOT NULL DEFAULT 'published'
);
CREATE TABLE quiz_topics (
  slug        TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  emoji       TEXT NOT NULL,
  difficulty  TEXT NOT NULL DEFAULT 'medio',    
  status      TEXT NOT NULL DEFAULT 'draft',
  sort_order  INTEGER NOT NULL DEFAULT 0
, color TEXT NOT NULL DEFAULT '#7c3aed', card_colors TEXT NOT NULL DEFAULT '["#f59e0b","#2563eb","#16a34a","#db2777"]');
CREATE TABLE quiz_questions (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  topic_slug     TEXT NOT NULL REFERENCES quiz_topics (slug) ON DELETE CASCADE,
  prompt         TEXT NOT NULL,
  choices_json   TEXT NOT NULL,
  correct_index  INTEGER NOT NULL,
  explanation    TEXT,
  difficulty     TEXT NOT NULL DEFAULT 'medio',
  times_shown    INTEGER NOT NULL DEFAULT 0,
  times_correct  INTEGER NOT NULL DEFAULT 0,
  status         TEXT NOT NULL DEFAULT 'draft',
  source         TEXT NOT NULL DEFAULT 'seed',
  created_at     INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE api_rate_limits (
  binding            TEXT PRIMARY KEY,
  next_available_at  INTEGER NOT NULL
);
CREATE TABLE guesses (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  category       TEXT NOT NULL,
  prompt         TEXT NOT NULL,
  choices_json   TEXT NOT NULL,
  correct_index  INTEGER NOT NULL,
  real_value     TEXT NOT NULL,
  explanation    TEXT,
  times_shown    INTEGER NOT NULL DEFAULT 0,
  times_correct  INTEGER NOT NULL DEFAULT 0,
  status         TEXT NOT NULL DEFAULT 'draft',
  source         TEXT NOT NULL DEFAULT 'seed',
  created_at     INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE daily_challenges (
  id                     INTEGER PRIMARY KEY AUTOINCREMENT,
  category               TEXT NOT NULL,
  answer                 TEXT NOT NULL,
  accepted_answers_json  TEXT NOT NULL,
  clues_json             TEXT NOT NULL,
  status                 TEXT NOT NULL DEFAULT 'draft',
  source                 TEXT NOT NULL DEFAULT 'gemini',
  created_at             INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE daily_results (
  play_date     TEXT PRIMARY KEY,
  challenge_id  INTEGER NOT NULL,
  hits_1        INTEGER NOT NULL DEFAULT 0,
  hits_2        INTEGER NOT NULL DEFAULT 0,
  hits_3        INTEGER NOT NULL DEFAULT 0,
  hits_4        INTEGER NOT NULL DEFAULT 0,
  hits_5        INTEGER NOT NULL DEFAULT 0,
  misses        INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE stories (
  slug        TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  category    TEXT NOT NULL,
  color       TEXT NOT NULL,
  card_colors TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'draft',
  sort_order  INTEGER NOT NULL DEFAULT 0
, for_date TEXT);
CREATE TABLE story_nodes (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  story_slug        TEXT NOT NULL REFERENCES stories (slug) ON DELETE CASCADE,
  is_root           INTEGER NOT NULL DEFAULT 0,
  is_ending         INTEGER NOT NULL DEFAULT 0,
  text              TEXT NOT NULL,
  choice_a_label    TEXT,
  choice_a_next_id  INTEGER REFERENCES story_nodes (id),
  choice_b_label    TEXT,
  choice_b_next_id  INTEGER REFERENCES story_nodes (id),
  times_reached     INTEGER NOT NULL DEFAULT 0
, outcome TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX dilemmas_status_idx ON dilemmas (status, category);
CREATE INDEX ranking_entries_list_idx ON ranking_entries (list_slug, status);
CREATE INDEX quiz_questions_topic_idx ON quiz_questions (topic_slug, status);
CREATE INDEX guesses_status_idx ON guesses (status);
CREATE INDEX daily_challenges_status_idx ON daily_challenges (status);
CREATE INDEX story_nodes_story_idx ON story_nodes (story_slug);
