INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(1,'jogador','Cristiano Ronaldo','["Cristiano Ronaldo","CR7","Ronaldo","Cristiano"]','["Nasci numa ilha portuguesa no meio do Atlântico.","Já vesti a camisa de Manchester United, Real Madrid, Juventus e Al-Nassr.","Um dos meus apelidos mais famosos é uma sigla com minhas iniciais e um número.","Sou o maior artilheiro da história de seleções nacionais de futebol.","Jogo com a camisa 7 e comemoro meus gols pulando e girando no ar."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(2,'país','Japão','["Japão"]','["Sou um conjunto de ilhas no Oceano Pacífico.","Minha capital está entre as maiores áreas metropolitanas do mundo.","Sou conhecido por sushi, mangá e trens-bala superrápidos.","Fui o único país a sofrer ataques com bombas atômicas, em 1945.","Minha bandeira é branca com um círculo vermelho no centro."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(3,'animal','Elefante','["Elefante","Elefante Africano"]','["Sou o maior animal terrestre vivo no planeta.","Minhas orelhas grandes me ajudam a perder calor do corpo.","Uso meu nariz comprido para beber água, comer e me comunicar.","Vivo em grupos liderados por uma fêmea mais velha, a matriarca.","Tenho presas de marfim que, infelizmente, atraem caçadores ilegais."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(4,'filme','Titanic','["Titanic"]','["Sou um filme baseado numa tragédia real de 1912.","Minha história é sobre um casal de classes sociais diferentes.","Tenho uma cena famosa na proa de um navio, de braços abertos.","Meu navio bateu num iceberg no Oceano Atlântico Norte.","Minha canção-tema é cantada por Céline Dion."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(5,'objeto','Guarda-chuva','["Guarda-chuva","Guarda chuva","Sombrinha"]','["Sou um objeto que você espera nunca precisar, mas é bom ter por perto.","Fico dobrado e guardado na maior parte do tempo.","Tenho hastes que se abrem formando um círculo.","Uso mais em dias nublados do que em dias de sol.","Te protejo da chuva quando abro por cima da sua cabeça."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(6,'jogador','Michael Jordan','["Michael Jordan","Jordan","MJ"]','["Sou um ex-atleta americano considerado por muitos o maior da história do meu esporte.","Joguei a maior parte da carreira por um time de Chicago.","Ganhei seis títulos de campeão na década de 1990.","Tenho uma marca de tênis com meu nome e o símbolo de um salto.","Uso o número 23 e sou uma lenda do basquete."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(7,'país','Brasil','["Brasil"]','["Sou o maior país da América do Sul.","Minha língua oficial é diferente da maioria dos meus vizinhos.","Tenho a maior floresta tropical do mundo dentro do meu território.","Sou pentacampeão mundial de futebol.","Minha bandeira é verde e amarela, com um círculo azul estrelado."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(8,'animal','Girafa','["Girafa"]','["Sou o animal terrestre mais alto do mundo.","Meu pescoço comprido tem o mesmo número de vértebras que o seu: sete.","Vivo nas savanas da África.","Minha pele tem um padrão de manchas único, como uma impressão digital.","Uso minha língua escura e comprida para pegar folhas bem alto nas árvores."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(9,'filme','Star Wars','["Star Wars","Guerra nas Estrelas"]','["Sou uma franquia de filmes que começou em 1977.","Minha história se passa \"há muito tempo, numa galáxia muito distante\".","Tenho cavaleiros que usam espadas de luz e sentem \"a Força\".","Um dos meus vilões mais famosos respira pesado e usa capacete preto.","Minha frase mais famosa é \"Que a Força esteja com você\"."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(10,'personagem','Batman','["Batman","Homem-Morcego","Bruce Wayne"]','["Sou um herói de quadrinhos sem superpoderes, só muita tecnologia e treino.","De dia sou um bilionário; à noite, viro outra pessoa.","Moro numa mansão com um mordomo leal chamado Alfred.","Meu maior inimigo é um vilão de rosto pintado de branco que sempre sorri.","Uso uma capa preta e um símbolo de morcego no peito."]','published','seed',1788871022);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(11,'Animal','Onça-pintada','["Onça-pintada","Onça pintada","Onça"]','["Meu nome científico carrega uma palavra grega que significa ''semelhante a uma pantera''.","Sou um felino solitário e excelente nadador, gostando de rios e áreas alagadas.","Minhas rosetas contêm pequenas manchas pretas em seu interior, o que me diferencia de outros grandes felinos manchados.","Sou o maior felino das Américas e o terceiro maior do mundo.","Estampa de papel moeda brasileiro, sou o felino mais emblemático das nossas matas."]','published','gemini',1788871306);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(12,'Filme','O Auto da Compadecida','["O Auto da Compadecida","Auto da Compadecida"]','["Minha trilha sonora original foi composta por Mú Carvalho e evoca o imaginário nordestino.","A base para a minha história veio de um texto escrito originalmente para o teatro na década de 1950.","Meus dois protagonistas principais ganham a vida aplicando pequenos golpes no interior da Paraíba.","A famosa frase ''Não sei, só sei que foi assim'' é um dos meus diálogos mais marcantes.","Conta as aventuras de João Grilo e Chicó na cidade de Taperoá e o julgamento final deles."]','published','gemini',1788871306);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(13,'Objeto do dia a dia','Fio dental','["Fio dental","Fio-dental"]','["Minha invenção moderna é atribuída a um dentista de Nova Orleans no século XIX.","Sou frequentemente recomendado por profissionais de saúde antes da escovação.","Posso ser encontrado em versões enceradas, com sabor de menta ou até expandidas.","Sou um filamento fino projetado para alcançar locais onde as cerdas da escova não entram.","Uso-me diariamente para remover restos de comida e placa bacteriana entre os dentes."]','published','gemini',1788871306);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(14,'Animal','Capivara','["Capivara","A capivara"]','["Possuo uma glândula especial perto do ânus que uso para marcar território.","Meus olhos, orelhas e narinas ficam alinhados no topo da minha cabeça para facilitar a respiração enquanto nado.","Sou considerada o maior roedor do mundo atualmente.","Apesar de ser um animal silvestre, tornei-me um símbolo cultural muito associado a parques urbanos e à internet no Brasil.","Sou um mamífero semi-aquático de pelagem marrom-acinzentada, muito pacífico e popularmente conhecido por não me estressar com nada."]','published','gemini',1788872001);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(15,'Filme','Cidade de Deus','["Cidade de Deus","Filme Cidade de Deus"]','["A maioria do elenco principal foi selecionada em oficinas de atuação realizadas em comunidades do Rio de Janeiro.","Fui indicado a quatro prêmios Oscar, incluindo o de melhor direção.","A minha trilha sonora traz clássicos do samba-rock e da MPB que marcam a transição temporal das cenas.","A minha famosa frase inicial diz: ''Se correr o bicho pega, se ficar o bicho come''.","Sou um aclamado filme brasileiro dirigido por Fernando Meirelles e Kátia Lund, que narra a ascensão do crime organizado na zona oeste carioca."]','published','gemini',1788872001);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(16,'Objeto do dia a dia','Cafeteira','["Cafeteira","Cafeteira elétrica","Cafeteira italiana"]','["Minhas versões mais antigas utilizavam um coador de pano sustentado por um aro de metal ou madeira.","O físico italiano Luigi Bezzera patenteou um mecanismo meu que mudou para sempre a extração comercial por pressão.","Em escritórios pelo mundo, costumo ser o ponto de encontro preferido para breves pausas durante o expediente.","Funcionço aquecendo água e fazendo-a passar por um pó finamente torrado e moído.","Sou o eletrodoméstico ou utensílio essencial para preparar a bebida escura e estimulante que desperta milhões de brasileiros todas as manhãs."]','published','gemini',1788872001);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(17,'Invenção','Avião','["Avião","Aviao","Aeroplano"]','["Minha criação envolveu anos de testes com papéis e pipas antes de ganhar o formato definitivo.","Sou associado a uma famosa disputa histórica sobre quem foi o verdadeiro pioneiro nos céus.","Cruzei os ares de Paris em 1906 sob o olhar atento da imprensa e de entusiastas.","Meu inventor brasileiro deu meu nome a um célebre relógio de pulso.","Sou o 14-Bis, a famosa criação de Alberto Santos Dumont."]','published','gemini',1788872119);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(18,'Filme','Central do Brasil','["Central do Brasil","O filme Central do Brasil"]','["Minha trilha sonora principal foi composta por Antonio Pinto e Jaques Morelenbaum.","Fui indicado ao Oscar nas categorias de Melhor Filme Estrangeiro e Melhor Atriz.","Minha história começa na agitada estação de trens mais famosa do Rio de Janeiro.","Acompanho a jornada de Dora, uma mulher cínica que escreve cartas para analfabetos.","Sou o clássico drama dirigido por Walter Salles e estrelado por Fernanda Montenegro."]','published','gemini',1788872120);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(19,'Animal','Arara-azul','["Arara-azul","Arara azul"]','["Tenho plumas adaptadas para filtrar toxinas de certas sementes que consumo na natureza.","Meu bico é extremamente forte e capaz de quebrar castanhas duras com facilidade.","Formo pares monogâmicos que duram por toda a vida reprodutiva.","Sou a maior espécie da minha família em todo o mundo.","Apresento uma vibrante plumagem azul-cobalto com detalhes amarelos ao redor dos olhos e do bico."]','published','gemini',1788872120);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(20,'Animal','Boto-cor-de-rosa','["Boto-cor-de-rosa","Boto cor de rosa","Boto","Boto rosa"]','["Possuo uma vértebra cervical que não é fundida, o que me permite girar a cabeça em 90 graus.","Em certas regiões, carrego a fama mítica de me transformar em homem elegante durante as festas juninas.","Sou o maior cetáceo de água doce do mundo.","Habito principalmente as bacias dos rios Amazonas e Orinoco.","Sou um famoso mamífero aquático da Amazônia conhecido pela minha coloração rosada."]','published','gemini',1788872231);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(21,'Filme','Tropa de Elite','["Tropa de Elite","Tropa de elite 1"]','["Fui adaptado a partir de um livro escrito por um ex-capitão da PM e um sociólogo.","Venci o Urso de Ouro de melhor filme no Festival de Berlim.","Minhas falas viraram memes e bordões populares na internet e nas ruas brasileiras.","Apresento a rotina intensa e os métodos rigorosos de uma força tática de segurança do Rio de Janeiro.","Meu protagonista icônico é o Capitão Nascimento, que eternizou a frase ''Pede pra sair!''."]','published','gemini',1788872231);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(22,'Objeto','Chave de fenda','["Chave de fenda","Chave de fendas"]','["Fui mencionada no título de uma famosa comédia romântica brasileira dos anos 2000.","Posso ser encontrada tanto em caixas de ferramentas manuais quanto no interior de aparelhos eletrônicos para manutenção.","Meu cabo costuma ser feito de plástico ou borracha isolante para maior segurança.","Minha ponta possui o formato ideal para encaixar em ranhuras de parafusos comuns.","Sou uma ferramenta manual básica utilizada para apertar ou desaparafusar parafusos."]','published','gemini',1788872231);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(23,'Animal','Tamanduá-bandeira','["Tamanduá-bandeira","Tamandua bandeira","Tamanduá"]','["Possuo uma visão e audição fracas, mas meu olfato é extremamente apurado.","Minha cauda longa e peluda serve tanto para equilibrar meu corpo quanto para me cobrir enquanto durmo.","Não tenho dentes; minha mandíbula é longa e tubular.","Minha língua pode medir até 40 centímetros de comprimento e é coberta por uma saliva pegajosa.","Sou um mamífero brasileiro conhecido por me alimentar principalmente de formigas e cupins."]','published','gemini',1788872517);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(24,'Filme','O Rei Leão','["O Rei Leão","Rei Leão","The Lion King"]','["Meu desenvolvimento foi arriscado dentro do estúdio, considerado secundário em relação a outro projeto lançado na mesma época.","A famosa cena da manada de gnus exigiu que animadores criassem um software totalmente novo para gerar o movimento em massa.","A frase mais famosa que pronuncio e canto significa ''sem preocupações'' em sua origem linguística.","Minha história segue vagamente o enredo de uma tragédia clássica escrita por William Shakespeare.","Sou uma animação clássica da Disney sobre um leãozinho que precisa reassumir seu lugar na savana."]','published','gemini',1788872517);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(25,'Objeto do dia a dia','Pregador de roupa','["Pregador de roupa","Prendedor de roupa","Pregador","Prendedor"]','["Minha patente original data do final do século XIX, mas meu design atual com mola de metal popularizou-se muito depois.","Posso ser fabricado inteiramente em madeira ou em plástico injetado.","Meu princípio mecânico básico utiliza a alavanca de primeira classe combinada com tensão elástica.","Costumo ser guardado em um cesto ou balde junto com dezenas de irmãos idênticos.","Sirvo para prender peças de tecido molhadas em uma corda para que sequem ao vento."]','published','gemini',1788872518);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(26,'Animal','Tatu-bola','["Tatu-bola","Tatu bola","Tatu"]','["Minha espécie foi escolhida para ser mascote de um grande evento esportivo no Brasil.","Possuo uma carapaça dura formada por placas córneas que me protege de predadores.","Tenho a capacidade única de me enrolar completamente, formando uma esfera quase perfeita.","Sou um mamífero nativo do Brasil, encontrado principalmente na região Nordeste e no Cerrado.","Sou um tatu famoso justamente pelo meu mecanismo de defesa que lembra uma bola de futebol."]','published','gemini',1788872706);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(27,'Filme','Divertida Mente','["Divertida Mente","Divertida-mente","Inside Out"]','["Minha trilha sonora principal foi composta por Michael Giacchino.","A ideia para a minha história surgiu quando o diretor observou as mudanças de humor de sua filha.","A mente humana serve como o principal cenário para os acontecimentos da minha trama.","Meus protagonistas são a Alegria, a Tristeza, o Medo, a Raiva e a Nojinho.","Sou uma animação da Pixar que se passa dentro da cabeça de uma garotinha chamada Riley."]','published','gemini',1788872707);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(28,'Objeto do dia a dia','Tesoura','["Tesoura","Tesouras"]','["Minha invenção remonta a milhares de anos atrás, muito antes da Idade Média, originalmente feita de bronze ou ferro.","Meu princípio mecânico básico combina duas alavancas de primeira classe unidas por um eixo central.","Existo em versões especializadas para destros e canhotos, variando o encaixe dos dedos.","Sou muito utilizada em trabalhos escolares, cortes de cabelo e costura.","Tenho duas lâminas afiadas e corto papéis, tecidos e outros materiais quando acionada."]','published','gemini',1788872707);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(29,'Objeto do dia a dia','Ferro de passar','["Ferro de passar","Ferro","Ferro de passar roupa"]','["Minha origem mecânica usava carvão para atingir altas temperaturas.","A base inferior é a parte que realiza o meu trabalho principal.","Costumo trabalhar em conjunto com uma tábua estofada.","Preciso de uma tomada por perto para aquecer minha resistência interna.","Sirvo para desamassar camisas, calças e deixar as roupas lisinhas."]','published','gemini',1788876650);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(30,'Animal','Tartaruga','["Tartaruga","Tartarugas"]','["Faço parte de um grupo de répteis cujos ancestrais já andavam pela Terra na época dos dinossauros.","Dependo inteiramente da temperatura do ambiente externo para regular o calor do meu corpo.","Não tenho dentes; em vez disso, possuo um bico córneo para cortar os alimentos.","Carrego comigo uma estrutura óssea rígida que é fundida à minha coluna vertebral.","Sou famosa pela lentidão ao caminhar e pela carapaça protetora onde escondo a cabeça."]','published','gemini',1788876650);
INSERT INTO "daily_challenges" ("id","category","answer","accepted_answers_json","clues_json","status","source","created_at") VALUES(31,'Atleta','Ayrton Senna','["Ayrton Senna","Senna"]','["Disputei minha primeira corrida oficial de kart no Autódromo de Interlagos.","Conquistei minha primeira vitória na Fórmula 1 sob forte chuva em Estoril.","Fui eternizado por três conquistas mundiais na principal categoria do automobilismo.","Fiquei mundialmente famoso pela minha habilidade incomparável ao guiar pistas molhadas.","Sou um dos maiores ídolos do esporte brasileiro, tricampeão mundial de Fórmula 1."]','published','gemini',1788876651);
