INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(3632,'o-eco-dos-sussurros-no-domo',0,1,'Minha reação fria faz com que ele se feche por completo. O clima de romance desmorona e voltamos a ser apenas conhecidos distantes.',NULL,NULL,NULL,NULL,0,'derrota');
