INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(3634,'o-eco-dos-sussurros-no-domo',0,1,'Minha fuga repentina o deixa completamente confuso e sem entender nada. Ele se despede friamente e vai embora sem olhar para trás. Perdi a chance de viver algo lindo por pura insegurança.',NULL,NULL,NULL,NULL,0,'derrota');
INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(3635,'o-eco-dos-sussurros-no-domo',0,0,'Sua expressão suaviza e ele segura minhas mãos com carinho. A proximidade física intensifica a conexão e o silêncio ao nosso redor parece magnético. Ele pergunta se podemos ir a um lugar mais reservado.','🤝 Aceito e sigo com ele',3633,'🏃‍♂️ Saio correndo de repente',3634,0,NULL);
