INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(4642,'o-ponto-de-impacto',0,0,'A espessura do vidro laminado resistiu parcialmente antes de ceder ao torque aplicado. Há resíduos de metal cravados nas bordas cortantes da abertura. Essa liga metálica específica aponta para um tipo bem restrito de chave de fenda.','🧲 Passo o ímã nos resíduos',4638,'🔍 Fotografo os resíduos metálicos',4641,0,NULL);
