INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(5409,'o-misterio-da-chave-oxidada',0,1,'Um curto-circuito em uma fiação antiga incendeia o papel antigo em segundos. Suas mãos queimam e a evidência vira cinzas. Derrota.',NULL,NULL,NULL,NULL,0,'derrota');
