INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(5630,'soterrado-na-encosta',1,0,'A terra cede de repente sob meus pés, e escorrego para o fundo de um barranco lamacento. Ouço o barulho de mais terra desabando logo acima de mim, enquanto a poeira fina começa a sufocar minha respiração. Proteger as vias aéreas criando um bolsão de ar com os braços é vital agora, pois a asfixia por partículas finas é o maior perigo imediato.','🤲 Cruzar braços no rosto',5618,'🧗 Tentar escalar a encosta',5629,0,NULL);
