INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(6410,'o-laboratorio-de-corpos-de-pantano',0,0,'O jato de ar gelado do duto afasta temporariamente a névoa densa e as silhuetas ao redor. O caminho até a escada de serviço está desimpedido por enquanto.','🏃 Subo a escada correndo.',6408,'🔦 Uso a lanterna para buscar ajuda.',6409,0,NULL);
