INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(6416,'o-laboratorio-de-corpos-de-pantano',0,0,'As chaves balançam no gancho enquanto as luzes de emergência começam a piscar em vermelho escuro. O reflexo no vidro mostra que os corpos nas cubas já não estão mais submersos. Eles flutuam em pé dentro do líquido, encarando suas costas.','🗝️ Pego o molho de chaves.',6412,'🧯 Disparo o extintor de CO2.',6415,0,NULL);
