INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(6418,'o-laboratorio-de-corpos-de-pantano',1,0,'O cheiro de turfa úmida e ácido tânico toma conta da sala escura onde repousam os antigos corpos de pântano. A turfa ácida e sem oxigênio do solo conserva a pele e os cabelos intactos por milênios, parecendo que ainda dormem. Um ruído de passos secos ecoa entre os tanques de vidro, embora a porta trancada devesse garantir sua solidão.','🔦 Ilumino os tanques à frente.',6406,'🔍 Investigo o painel de controle.',6417,0,NULL);
