INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(7091,'frente-de-fogo',1,0,'O vento empurra labaredas velozes pela vegetação seca bem na minha direção. Como o fogo se alastra mais rápido morro acima devido ao ar quente que sobe, fugir para o alto é uma armadilha fatal. Preciso decidir o rumo imediato da fuga.','📉 Desço correndo para a baixada',7079,'↔️ Rodo para a lateral do vento',7090,0,NULL);
INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(7092,'o-fator-sutil-da-atracao',0,1,'Sua abordagem foi rápida demais e acabou assustando a pessoa, que sorriu sem graça, disse ter compromisso e foi embora.',NULL,NULL,NULL,NULL,0,'derrota');
