INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(8008,'o-misterio-da-interseccao-de-trincas',0,0,'Ao girar rapidamente, você fica cara a cara com o curador da galeria segurando um pedaço de ferro idêntico ao do arrombamento. Ele sorri cinicamente, percebendo que você descobriu que o furto foi um golpe de seguro forjado. Apenas sua agilidade mental pode salvá-lo agora.','💬 Aponto a evidência das trincas.',8006,'👊 Avanço para desarmar o curador.',8007,0,NULL);
