INSERT INTO "story_nodes" ("id","story_slug","is_root","is_ending","text","choice_a_label","choice_a_next_id","choice_b_label","choice_b_next_id","times_reached","outcome") VALUES(8057,'sufoco-na-serra',1,0,'O céu escurece de repente e raios começam a estalar perto da sua barraca na serra. A descarga elétrica de um raio pode viajar pelo chão e atingir quem está em pé, então o melhor é ficar agachado com os pés juntos. O temporal desaba com força e o vento ameaça arrancar a lona.','⛺ Reforço os ganchos da barraca.',8045,'🏃‍♂️ Corro para abrigo na mata.',8056,0,NULL);
